int batchSize = 50;
for (int i = 0; i < items.size(); i++) {
    session.persist(items.get(i));
    if (i % batchSize == 0 && i > 0) {
        session.flush(); // wysyla zgromadzone operacje do bazy
        session.clear(); // czysci cache pierwszego poziomu, zwalnia pamiec
    }
}

