// POPRAWNIE: equals() po kluczu glownym, dziala niezaleznie od sesji
@Override
public boolean equals(Object o) {
    if (this == o) return true;
    if (!(o instanceof Book)) return false;
    Book other = (Book) o;
    return id != null && id.equals(other.id);
}

